import{_ as e,o as a,c as i,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Administrator","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/index.md","filePath":"src/en/guide/admin/index.md"}'),s={name:"en/guide/admin/index.md"};function n(d,t,o,u,l,c){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="administrator" tabindex="-1">Administrator <a class="header-anchor" href="#administrator" aria-label="Permalink to &quot;Administrator&quot;">​</a></h1><p>As an administrator, you have access to your school&#39;s entire structure: base configuration, staff, students, pricing, timetables, and report cards. It&#39;s ERA&#39;s most complete role — most other roles (teacher, front office, cashier...) work within a scope you&#39;ve set up beforehand.</p><h2 id="where-to-find-the-admin-tools" tabindex="-1">Where to find the admin tools <a class="header-anchor" href="#where-to-find-the-admin-tools" aria-label="Permalink to &quot;Where to find the admin tools&quot;">​</a></h2><p>There isn&#39;t a single &quot;Administration&quot; menu: depending on what you want to do, you&#39;ll find it in one of the sections of the left-hand menu:</p><ul><li><strong>Users</strong> and <strong>Activity Log</strong> appear near the top of the menu, just below the dashboard.</li><li><strong>School Structure</strong> groups academic years, sites, departments, classes, and students.</li><li><strong>Grades</strong> groups subjects, evaluation types, academic periods, subjects by department, competencies, and teacher assignments.</li><li><strong>Payments</strong> contains fee structures and billing.</li><li>Employees and staff transfers appear under the <strong>Employees</strong> section.</li><li><strong>Extracurricular Activities</strong> groups the activity catalog and its sessions.</li><li><strong>App Settings</strong> (near the top of the menu) customises your instance and controls two behaviours that affect other users — see <a href="/era-guide/en/guide/admin/parametres-application.html">App settings</a>.</li><li><strong>Homepage</strong>, just above it, edits the public page families see on the school&#39;s address — see <a href="/era-guide/en/guide/admin/page-accueil.html">Homepage</a>.</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Guide page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/era-guide/en/guide/admin/tableau-de-bord.html">Dashboard</a></td><td>The school&#39;s management indicators (headcount, results, absence rate, cash flow) and how to export them</td></tr><tr><td><a href="/era-guide/en/guide/admin/structure-etablissement.html">School structure</a></td><td>Academic years, periods, sites, departments, classes, subjects, competency frameworks, and evaluation types — the base setup to do at the start of the year</td></tr><tr><td><a href="/era-guide/en/guide/admin/personnel-utilisateurs.html">Staff and user accounts</a></td><td>Creating accounts and assigning them a role, managing staff records and contracts, assigning teachers, handling site transfer requests</td></tr><tr><td><a href="/era-guide/en/guide/admin/eleves-tuteurs.html">Students and guardians</a></td><td>Student records, student and guardian accounts, specialty subject choices</td></tr><tr><td><a href="/era-guide/en/guide/admin/frais-tarification.html">Fees and pricing</a></td><td>Fee structures per site/department/year and discounts granted to students</td></tr><tr><td><a href="/era-guide/en/guide/admin/emplois-du-temps.html">Timetables</a></td><td>Building each class&#39;s weekly timetable</td></tr><tr><td><a href="/era-guide/en/guide/admin/bulletins.html">Report cards</a></td><td>Publishing and downloading a class&#39;s report cards for a given period</td></tr><tr><td><a href="/era-guide/en/guide/admin/activites-extrascolaires.html">Extracurricular activities</a></td><td>Building the extracurricular activity catalog and scheduling its sessions</td></tr><tr><td><a href="/era-guide/en/guide/admin/page-accueil.html">Homepage</a></td><td>Configuring the school&#39;s public page: tagline, introduction, departments and FAQ</td></tr><tr><td><a href="/era-guide/en/guide/admin/parametres-application.html">App settings</a></td><td>Identity, colors, logos, receipt customisation, and the two settings that change how the app behaves</td></tr><tr><td><a href="/era-guide/en/guide/admin/demo-et-journal.html">Full demo and activity log</a></td><td>Activating the full demo (Era Admission tenants on the free tier) and reviewing the action history</td></tr></tbody></table><p>Settings that relate to your own account (profile, security, notifications, language) are shared by all roles — see <a href="/era-guide/en/guide/prise-en-main.html">Getting started</a>.</p>',8)])])}const m=e(s,[["render",n]]);export{g as __pageData,m as default};
